import{_ as s,c as a,o as i,a5 as r}from"./chunks/framework.CnICWABh.js";const m=JSON.parse('{"title":"Device Screen","description":"","frontmatter":{},"headers":[],"relativePath":"devices/api/messages/overview-screen.md","filePath":"devices/api/messages/overview-screen.md"}'),n={name:"devices/api/messages/overview-screen.md"};function c(t,e,o,d,l,p){return i(),a("div",{"data-pagefind-body":!0},e[0]||(e[0]=[r('<div class="danger custom-block"><p class="custom-block-title">⚠️ Not yet public</p><p>The Device API currently in development and is not yet accessible on production devices.</p><p>These pages can be seen as a view of what is to come later this year.</p></div><h1 id="device-screen" tabindex="-1">Device Screen <a class="header-anchor" href="#device-screen" aria-label="Permalink to &quot;Device Screen&quot;">​</a></h1><p>A dedicated group of messages for displaying on device Eink screens (currently only monochrome eink of size 122x250 pixels)</p><p>All screen messages have a Page ID field (3) defined, which tracks which screen is currently being rendered.</p><p>A single screen can be created (buffered), updated and displayed over multiple messages, all of which should have the same page ID.</p><p>Page Ids may also be used in other messages, emitting certain events, such as button presses during menu navigation.</p><p><strong>Page ID ranges</strong></p><ul><li>0, Reserved for initial device page draws</li><li>1-10, Reserved for hard coded device pages</li><li>100+, Recommended range for custom page IDs</li></ul>',8)]))}const g=s(n,[["render",c]]);export{m as __pageData,g as default};
